#define KALEIDO 1
#define LIGHTCOUNT 100
#define v2Resolution iResolution
#define out_color fragColor
#define time iTime
#define pi 3.141592

// Funzione di random migliorata per più variazione
vec2 r2(vec2 uv) {
    return fract(sin(uv*vec2(1734.821,3175.371)+uv.yx*vec2(5127.135,8239.123)+vec2(2134.93,2347.367))*vec2(3213.523744,874.93242));
}

vec2 r2(int i) {
    return fract(sin(float(i)*vec2(1734.821,3175.371)+vec2(2134.93,2347.367))*vec2(3213.523744,874.93242));
}

// Rotazione modificata per movimento più fluido
mat2 rot(float a) {
    float ca=cos(a * 1.2); // Velocità di rotazione aumentata
    float sa=sin(a * 1.2);
    return mat2(ca,sa,-sa,ca);
}

// Funzione mirror modificata per pattern più complessi
vec2 mir(vec2 uv, float a) {
    mat2 ra=rot(a);
    uv *= ra;
    uv.y=abs(uv.y);
    uv.x=abs(uv.x); // Aggiunto mirror sull'asse x
    uv *= ra;
    return uv;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = vec2(fragCoord.x / v2Resolution.x, fragCoord.y / v2Resolution.y);
    uv -= 0.5;
    uv /= vec2(v2Resolution.y / v2Resolution.x, 1);
    float mt=time*0.15; // Rallentato leggermente

#if KALEIDO
    uv = mir(uv, mt*0.3);  // Modificati i valori per un pattern diverso
    uv = mir(uv, -mt*0.5);
    uv = mir(uv, mt*0.7);
    uv = mir(uv, -mt*0.8);
#endif

    float ht=time*0.25;
    uv += abs(vec2(sin(ht*1.2),cos(ht*0.8)))*(sin(time*0.4)*0.4+0.4)*0.25;

    // Nuova palette di colori più scura
    vec3 tcol=mix(vec3(0.2,0.05,0.3),vec3(0.1,0.3,0.4),sin(1534.12134+time*vec3(0.4,1.1,2.2)));

    float pt=time*0.15;
    float pulse = abs(fract(pt*floor(abs(fract(pt*3.0)*3.0-0.5)*2.0))-0.5)*2.0;
    float st=time*0.25;
    float d=10000.0;
    vec3 col = vec3(0);

    for(int i=0; i<LIGHTCOUNT; ++i) {
        vec2 rr=r2(i*12); // Modificato per più variazione
        float a=rr.x*pi*2.0 + st + sin(st*0.7+rr.y)*1.5 + sin(st*0.3+rr.y)*0.8;
        vec2 p = uv+(r2(i)-0.5)*0.4 + vec2(cos(a),sin(a))*0.25;
        float lp=length(p);
        d=min(d,lp-0.015);

        // Nuovi colori per le luci
        vec3 lcol=mix(vec3(0.15,0.05,0.2),vec3(0.1,0.2,0.3),sin(rr.y*120.0*vec3(0.4,1.1,2.2)));
        lcol = mix(lcol,tcol,pulse);
        float bd = 0.002/lp;
        col += lcol*bd;
    }

    float gt=time*0.25;
    vec3 lcol=mix(vec3(0.15,0.05,0.2),vec3(0.1,0.2,0.3),sin(time*vec3(0.4,1.1,2.2)));
    col += abs(fract(gt*floor(abs(fract(gt*3.0)*3.0)-0.5)*2.0)-0.5)*2.0
           *lcol*pow(abs(fract(d*25.0-time*0.8)-0.5)*2.0,6.0)
           *max(0.0,0.5 / length(uv)-0.8);

    out_color = vec4(col,0);
}
